before:
Complete local C example; the app itself does not execute it:
```c
#include <stdio.h>
#include <stdlib.h>
static int prepare(int accept) {
    int status = 1;
    int *value = malloc(sizeof *value);
    if (value == NULL) return 1;
    if (!accept) goto cleanup;
    *value = 7;
    status = 0;
cleanup:
    free(value);
    return status;
}
int main(void) {
    printf("%d\n", prepare(1));
    return 0;
}
```

